<div class="settings-admin-header"><div><p class="eyebrow">Central configuration</p><h1>Website settings</h1><p class="admin-lead">Manage the shared identity, footer and About Us content used across the public website.</p></div></div>
<div class="settings-admin-grid">
    <section class="panel settings-card"><div class="settings-card-heading"><span class="settings-card-icon"><i class="bi bi-app-indicator"></i></span><div><h2>Favicon settings</h2><p>Generate browser, bookmark and mobile icon sizes from one verified asset.</p></div></div><form method="post" enctype="multipart/form-data" action="<?= e(url('admin/settings')) ?>" class="settings-form"><?= csrf_field() ?><input type="hidden" name="section" value="favicon"><?php $favicon = settings('favicon_32', ''); ?><?php if ($favicon): ?><img class="settings-favicon-preview" src="<?= e(media_url($favicon)) ?>" alt="Current SLGTI favicon"><?php else: ?><div class="settings-logo-fallback settings-favicon-preview"><i class="bi bi-app-indicator"></i><span>Default favicon will be used</span></div><?php endif; ?><label>Upload favicon <input type="file" name="favicon" accept=".ico,image/x-icon,image/png,image/jpeg,image/webp,image/gif,image/svg+xml" <?= $favicon ? '' : 'required' ?>></label><small>ICO, PNG, JPEG, WEBP, GIF or safely validated SVG. Raster files generate 16, 32, 48, 180, 192 and 512px PNG variants.</small><?php if ($favicon): ?><label class="checkbox-label"><input type="checkbox" name="remove_favicon" value="1"> Remove custom favicon and use fallback</label><?php endif; ?><button class="button" type="submit">Save favicon</button></form></section>
    <section class="panel settings-card"><div class="settings-card-heading"><span class="settings-card-icon"><i class="bi bi-image"></i></span><div><h2>Header logo settings</h2><p>Update the responsive official logo and alternative text.</p></div></div><form method="post" enctype="multipart/form-data" action="<?= e(url('admin/settings')) ?>" class="settings-form"><?= csrf_field() ?><input type="hidden" name="section" value="logo"><?php $logo = settings('site_logo', ''); ?><?php if ($logo): ?><img class="settings-logo-preview" src="<?= e(media_url($logo)) ?>" alt="<?= e(settings('site_logo_alt', 'SLGTI')) ?>"><?php else: ?><div class="settings-logo-fallback"><i class="bi bi-image"></i><span>Default logo will be used</span></div><?php endif; ?><label>Upload replacement logo <input type="file" name="site_logo" accept="image/jpeg,image/png,image/webp,image/gif"></label><label>Alternative text <input type="text" name="site_logo_alt" value="<?= e(settings('site_logo_alt', 'Sri Lanka German Training Institute')) ?>" maxlength="180" required></label><div class="settings-form-columns"><label>Display width (px) <input type="number" name="site_logo_width" min="80" max="500" value="<?= (int) settings('site_logo_width', '220') ?>"></label><label>Maximum height (px) <input type="number" name="site_logo_height" min="24" max="180" value="<?= (int) settings('site_logo_height', '52') ?>"></label></div><?php if ($logo): ?><label class="checkbox-label"><input type="checkbox" name="remove_site_logo" value="1"> Remove custom logo and use fallback</label><?php endif; ?><button class="button" type="submit">Save header logo</button></form></section>
    <section class="panel settings-card settings-card-wide"><div class="settings-card-heading"><span class="settings-card-icon"><i class="bi bi-layout-text-window-reverse"></i></span><div><h2>Footer settings</h2><p>Control contact details, social links and copyright information.</p></div></div><form method="post" enctype="multipart/form-data" action="<?= e(url('admin/settings')) ?>" class="settings-form"><?= csrf_field() ?><input type="hidden" name="section" value="footer"><div class="settings-form-columns"><label>Footer description <textarea name="footer_text" rows="4"><?= e(settings('footer_text', '')) ?></textarea></label><label>Address <textarea name="address" rows="4"><?= e(settings('address', '')) ?></textarea></label><label>Phone <input name="phone" value="<?= e(settings('phone', '')) ?>"></label><label>Alternate phone <input name="phone_alt" value="<?= e(settings('phone_alt', '')) ?>"></label><label>Fax <input name="fax" value="<?= e(settings('fax', '')) ?>"></label><label>Email <input type="email" name="email" value="<?= e(settings('email', '')) ?>"></label><label>Short location <input name="location_label" value="<?= e(settings('location_label', '')) ?>"></label><label>Office hours <input name="hours" value="<?= e(settings('hours', '')) ?>"></label><label>Facebook URL <input type="url" name="facebook_url" value="<?= e(settings('facebook_url', '')) ?>"></label><label>YouTube URL <input type="url" name="youtube_url" value="<?= e(settings('youtube_url', '')) ?>"></label><label>LinkedIn URL <input type="url" name="linkedin_url" value="<?= e(settings('linkedin_url', '')) ?>"></label><label>Website URL <input type="url" name="footer_website" value="<?= e(settings('footer_website', '')) ?>"></label><label>Copyright text <input name="footer_copyright" value="<?= e(settings('footer_copyright', '')) ?>"></label></div><label>Footer logo <input type="file" name="footer_logo" accept="image/jpeg,image/png,image/webp,image/gif"></label><?php if (settings('footer_logo', '')): ?><label class="checkbox-label"><input type="checkbox" name="remove_footer_logo" value="1"> Remove custom footer logo</label><?php endif; ?><label class="checkbox-label"><input type="checkbox" name="footer_visible" value="1" <?= settings('footer_visible', '1') === '1' ? 'checked' : '' ?>> Show footer</label><button class="button" type="submit">Save footer</button></form></section>
    <section class="panel settings-card settings-card-wide"><div class="settings-card-heading"><span class="settings-card-icon"><i class="bi bi-building"></i></span><div><h2>About Us settings</h2><p>Edit the published About Us page using the existing rich-text editor.</p></div><a class="button button-secondary" href="<?= e(url('about')) ?>" target="_blank" rel="noopener">Preview public page</a></div><?php if ($aboutPage): ?><form method="post" enctype="multipart/form-data" action="<?= e(url('admin/settings')) ?>" class="settings-form" id="settingsAboutForm"><?= csrf_field() ?><input type="hidden" name="section" value="about"><div class="settings-form-columns"><label>About title <input name="title" value="<?= e($aboutPage['title']) ?>" required></label><label>Publication status <select name="status"><option value="published" <?= $aboutPage['status'] === 'published' ? 'selected' : '' ?>>Published</option><option value="draft" <?= $aboutPage['status'] === 'draft' ? 'selected' : '' ?>>Draft</option></select></label></div><label>Short introduction <textarea name="excerpt" rows="3"><?= e($aboutPage['excerpt']) ?></textarea></label><label>Main About Us content <textarea name="body" class="richtext" rows="14"><?= e($aboutPage['body']) ?></textarea></label><div class="settings-form-columns"><label>Featured image <input type="file" name="image" accept="image/jpeg,image/png,image/webp,image/gif"><?php if ($aboutPage['image']): ?><img class="settings-about-preview" src="<?= e(media_url($aboutPage['image'])) ?>" alt="<?= e($aboutPage['image_alt'] ?: $aboutPage['title']) ?>"><?php endif; ?></label><label>Image alternative text <input name="image_alt" value="<?= e($aboutPage['image_alt'] ?: $aboutPage['title']) ?>"></label></div><?php if ($aboutPage['image']): ?><label class="checkbox-label"><input type="checkbox" name="remove_image" value="1"> Remove featured image</label><?php endif; ?><button class="button" type="submit">Save About Us</button></form><?php else: ?><p class="alert alert-warning">The About Us page record could not be found.</p><?php endif; ?></section>
</div>
<section class="panel settings-other"><h2>Other settings</h2><p class="panel-note">Existing site, SEO, homepage and admissions settings remain available here.</p><form method="post" action="<?= e(url('admin/settings')) ?>" class="form-grid"><?= csrf_field() ?><input type="hidden" name="section" value="other"><?php foreach ($grouped as $group => $rows): ?><?php foreach ($rows as $row): ?><?php if (in_array($row['setting_key'], $managedKeys, true)) continue; ?><label><?= e($row['label']) ?><?php if ($row['field_type'] === 'textarea'): ?><textarea name="settings[<?= e($row['setting_key']) ?>]" rows="3"><?= e($row['setting_value']) ?></textarea><?php elseif ($row['field_type'] === 'select'): ?><select name="settings[<?= e($row['setting_key']) ?>]"><option value="1" <?= $row['setting_value'] === '1' ? 'selected' : '' ?>>Yes</option><option value="0" <?= $row['setting_value'] === '0' ? 'selected' : '' ?>>No</option></select><?php else: ?><input name="settings[<?= e($row['setting_key']) ?>]" value="<?= e($row['setting_value']) ?>"><?php endif; ?></label><?php endforeach; ?><?php endforeach; ?><div class="form-actions"><button class="button" type="submit">Save other settings</button></div></form></section>
